-- Saldo inicial do estoque (Heitor, 10/10): o saldo atual da Eclética ("man. mat.xlsx", 09/10) é todo da Central de Produção;
-- as lojas, a Pizza e Eventos começam em zero. Saldo negativo na Eclética entra como zero.
-- Lança um ajuste por item = saldo desejado − saldo que já existe no portal, então rodar de novo não duplica.
create temp table _saldo_inicial (codigo text primary key, quantidade numeric, custo numeric) on commit drop;

with alvo as (
  select c.id as centro, i.id as insumo_id,
    case when c.id = 'central' then coalesce(s.quantidade, 0) else 0 end as quer,
    case when c.id = 'central' then coalesce(s.custo, i.preco) end as custo
  from centros_custo c cross join insumos i
  left join _saldo_inicial s on s.codigo = i.ecletica_codigo
), atual as (
  select centro_custo_id as centro, insumo_id, sum(quantidade) as tem from estoque_movimentos group by 1, 2
)
select a.centro, a.insumo_id, current_date, 'ajuste', a.quer - coalesce(t.tem, 0), a.custo, 'Saldo inicial (Eclética 09/10)'
from alvo a left join atual t on t.centro = a.centro and t.insumo_id = a.insumo_id
where a.quer - coalesce(t.tem, 0) <> 0;
